// FILE_REF: ./nodes/parse_vapi_payload.js
const body = $json.body || $json;
let callerPhone = body.message?.customer?.number || body.call?.customer?.number || body.caller_id || '';
let callSid = body.message?.call?.id || body.call?.id || 'CALL-' + Date.now();
let recordingUrl = body.message?.recordingUrl || body.recording_url || '';
let functionArgs = {};
if (body.message?.type === 'tool-calls' && body.message?.toolCalls?.length > 0) {
  functionArgs = body.message.toolCalls[0].function.arguments || {};
} else if (body.function_arguments) {
  functionArgs = body.function_arguments;
} else {
  functionArgs = body;
}
return [{ json: { callerPhone, callSid, recordingUrl, requestType: functionArgs.requestType || 'Leave', startDate: functionArgs.startDate, endDate: functionArgs.endDate, durationDays: parseInt(functionArgs.durationDays) || 1, reason: functionArgs.reason || 'Voice IVR Submission' } }];

// FILE_REF: ./nodes/validate_caller_id.js
const parsedCall = $('AI Speech Data Converter').first().json;
const dbMatch = $input.all()[0]?.json;
if (!dbMatch || !dbMatch.roll_no) {
  return [{ json: { isValidCaller: false, error: 'UNAUTHORIZED_CALLER_ID', callerPhone: parsedCall.callerPhone } }];
}
return [{ json: { isValidCaller: true, rollNo: dbMatch.roll_no, studentName: dbMatch.student_name, department: dbMatch.department, year: dbMatch.year, section: dbMatch.section, parentName: dbMatch.parent_name, parentPhone: dbMatch.parent_phone_number, advisorId: dbMatch.advisor_id, advisorEmail: dbMatch.advisor_email, requestType: parsedCall.requestType, startDate: parsedCall.startDate, endDate: parsedCall.endDate, durationDays: parsedCall.durationDays, reason: parsedCall.reason, callSid: parsedCall.callSid, recordingUrl: parsedCall.recordingUrl } }];
